//! Bounded two-sentence next-spell grants keep cast timing and entry programs.
#[path="custom_final_next_wave_support.rs"]mod support;
#[path="cf8_p08/play.rs"]mod play;
use ironsmith::{CardDefinition,GameState,ObjectId,Zone,PlayerId};
use ironsmith::decision::{DecisionMaker,SelectFirstDecisionMaker,LegalAction,compute_legal_actions};
const A:PlayerId=PlayerId::from_index(0);const B:PlayerId=PlayerId::from_index(1);
fn sources()->[CardDefinition;2]{let fixture:serde_json::Value=serde_json::from_str(include_str!("../../../fixtures/custom_mechanics/msem-final-real-source-next-wave.json")).unwrap();let source=fixture["mechanics"].as_array().unwrap().iter().flat_map(|row|row["representative_cards"].as_array().unwrap()).find(|card|card["name"]=="Skittish Prey").unwrap();support::definitions(source).unwrap()}
fn keyword(game:&GameState,id:ObjectId)->bool{game.current_characteristics(id).unwrap().abilities.iter().any(|ability|matches!(&ability.kind,ironsmith::ability::AbilityKind::Static(value) if value.custom_keyword_name().is_some_and(|name|name=="voracious")))}
fn castable(game:&GameState,id:ObjectId,player:PlayerId)->bool{compute_legal_actions(game,player).unwrap().iter().any(|action|matches!(action,LegalAction::CastSpell{spell_id,..}if *spell_id==id))}
fn resolve_source(game:&mut GameState,source:&CardDefinition){play::give_mana(game,A,ironsmith::mana::ManaSymbol::Green,12);play::cast(game,A,source,&mut play::Script::default());ironsmith::game_loop::resolve_stack_entry_with(game,&mut SelectFirstDecisionMaker).unwrap();}
struct Sacrifices{ids:Vec<ObjectId>,seen:bool}
impl DecisionMaker for Sacrifices{
 fn decide_boolean(&mut self,_:&GameState,_:&ironsmith::decisions::context::BooleanContext)->bool{true}
 fn decide_objects(&mut self,_:&GameState,ctx:&ironsmith::decisions::context::SelectObjectsContext)->Vec<ObjectId>{self.seen=true;assert_eq!(ctx.max,Some(2));for id in &self.ids{assert!(ctx.candidates.iter().any(|candidate|candidate.id==*id&&candidate.legal));}self.ids.clone()}
}
#[test]fn exact_source_compiles_direct_and_raw_artifact_with_whole_typed_parity(){let [native,artifact]=sources();let native=ironsmith_runtime_catalog::artifact_materializer::encode_runtime_definition(native).unwrap();let artifact=ironsmith_runtime_catalog::artifact_materializer::encode_runtime_definition(artifact).unwrap();assert_eq!(serde_json::to_value(native).unwrap(),serde_json::to_value(artifact).unwrap());}
#[test]fn source_allows_next_creature_off_turn_and_installs_identity_and_entry_program_as_it_is_cast(){
 for definition in sources(){let mut game=play::game();game.turn.active_player=B;game.turn.priority_player=Some(A);resolve_source(&mut game,&definition);assert!(game.battlefield.iter().filter_map(|id|game.object(*id)).any(|object|object.name=="Squirrel"));
  let recipient=play::vanilla("Independent creature","{1}","Elf",2,2);let other=ironsmith_compiler_runtime::compile_to_runtime_definition("Unrelated instant","Mana cost: {0}\nType: Instant\nYou gain 1 life.",false).unwrap();
  play::cast(&mut game,A,&other,&mut play::Script::default());ironsmith::game_loop::resolve_stack_entry_with(&mut game,&mut SelectFirstDecisionMaker).unwrap();
  game.turn.active_player=B;game.turn.priority_player=Some(A);let preview=game.create_object_from_definition(&recipient,A,Zone::Hand);let graveyard=game.create_object_from_definition(&recipient,A,Zone::Graveyard);assert!(!castable(&game,graveyard,A),"a timing permission grants no new origin-zone permission");assert!(castable(&game,preview,A));assert!(!keyword(&game,preview),"affordability/timing preview does not mutate the hand card");let spell=play::cast(&mut game,A,&recipient,&mut play::Script::default());assert!(keyword(&game,spell),"the actual cast incarnation receives the supplied keyword identity");
  let artifact=ironsmith_compiler_runtime::compile_to_runtime_definition("Sacrifice artifact","Type: Artifact",false).unwrap();let artifact=game.create_object_from_definition(&artifact,A,Zone::Battlefield);let creature=game.create_object_from_definition(&recipient,A,Zone::Battlefield);let enemy=game.create_object_from_definition(&recipient,B,Zone::Battlefield);let stable=game.object(spell).unwrap().stable_id;
  let mut dm=Sacrifices{ids:vec![artifact,creature],seen:false};ironsmith::game_loop::resolve_stack_entry_with(&mut game,&mut dm).unwrap();assert!(dm.seen);let entered=game.find_object_by_stable_id(stable).unwrap();assert_eq!(game.counter_count(entered,ironsmith::object::CounterType::PlusOnePlusOne),2);assert_eq!(game.calculated_power(entered),Some(4));assert!(keyword(&game,entered));assert_eq!(game.object(enemy).unwrap().zone,Zone::Battlefield);
  game.turn.priority_player=Some(A);let next=game.create_object_from_definition(&recipient,A,Zone::Hand);assert!(!castable(&game,next,A),"the first matching cast consumes the timing grant and ability grant once");
  let effect=ironsmith::Effect::move_to_zone(ironsmith::target::ChooseSpec::SpecificObject(entered),Zone::Hand,false);ironsmith::effects::execute_effect(&mut game,&effect,&mut ironsmith::effects::EffectContext::new_default(entered,A)).unwrap();let hand=game.find_object_by_stable_id(stable).unwrap();assert!(!keyword(&game,hand));let mut later=Sacrifices{ids:vec![],seen:false};let receipt=game.move_object_with_etb_processing_with_dm(hand,Zone::Battlefield,&mut later).unwrap();let fresh=receipt.original.into_result().unwrap().new_id;assert!(!later.seen);assert!(!keyword(&game,fresh));assert_eq!(game.counter_count(fresh,ironsmith::object::CounterType::PlusOnePlusOne),0);
 }
}
#[test]fn another_players_creature_does_not_consume_the_recipients_grants_and_turn_expiry_does(){for definition in sources(){let mut game=play::game();game.turn.active_player=B;game.turn.priority_player=Some(A);resolve_source(&mut game,&definition);let recipient=play::vanilla("Independent creature","{1}","Elf",2,2);game.turn.active_player=B;game.turn.priority_player=Some(B);play::give_mana(&mut game,B,ironsmith::mana::ManaSymbol::Green,2);let enemy=play::cast(&mut game,B,&recipient,&mut play::Script::default());assert!(!keyword(&game,enemy));ironsmith::game_loop::resolve_stack_entry_with(&mut game,&mut SelectFirstDecisionMaker).unwrap();game.turn.priority_player=Some(A);let own=game.create_object_from_definition(&recipient,A,Zone::Hand);assert!(castable(&game,own,A));game.next_turn();game.turn.active_player=B;game.turn.priority_player=Some(A);assert!(!castable(&game,own,A));}}
